mapper.select:
SELECT u.value_month, u.index_value FROM ( /* step2) 현재 기준 월물 — 최종 기준일(value_date 최대)의 미래 월물 */ SELECT o.value_month AS value_month, o.index_value AS index_value FROM tif_skgas_odin o WHERE o.index_id = #{indexId} AND o.index_div = 'F' AND o.value_date = ( SELECT MAX(m.value_date) FROM tif_skgas_odin m WHERE m.index_id = #{indexId} AND m.index_div = 'F' ) AND o.value_month <= #{toMonth}
UNION
/* step3) 현재 기준 이전 월물 — value_month별 최신 기준일 값 */ SELECT o.value_month AS value_month, o.index_value AS index_value FROM ( SELECT MAX(p.value_date) AS value_date, p.value_month AS value_month, p.index_id AS index_id FROM tif_skgas_odin p WHERE p.index_id = #{indexId} AND p.index_div = 'F' AND p.value_month >= #{fromMonth} AND p.value_month < ( SELECT MIN(c.value_month) FROM tif_skgas_odin c WHERE c.index_id = #{indexId} AND c.index_div = 'F' AND c.value_date = ( SELECT MAX(m.value_date) FROM tif_skgas_odin m WHERE m.index_id = #{indexId} AND m.index_div = 'F' ) ) GROUP BY p.value_month, p.index_id ) t JOIN tif_skgas_odin o ON o.value_date = t.value_date AND o.value_month = t.value_month AND o.index_id = t.index_id AND o.index_div = 'F' ) u ORDER BY u.value_month ASC
